{
  "version": "Notebook/1.0",
  "items": [
    {
      "type": 1,
      "name": "header",
      "content": {
        "json": "## Microsoft Entra Stale User Tracking\nPhase 1 monitor-and-report evidence from `EntraStaleUser_CL`. Threshold: no successful sign-in (`signInActivity.lastSuccessfulSignInDateTime`) within the configured inactivity window. This workbook does not notify or disable accounts."
      }
    },
    {
      "type": 9,
      "name": "parameters",
      "content": {
        "version": "KqlParameterItem/1.0",
        "style": "pills",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "parameters": [
          {
            "id": "6a3b7f0e-1d52-4b8f-9a61-3c2f6e1d0a01",
            "version": "KqlParameterItem/1.0",
            "name": "TimeRange",
            "type": 4,
            "isRequired": true,
            "value": {
              "durationMs": 604800000
            },
            "typeSettings": {
              "selectableValues": [
                {
                  "durationMs": 86400000
                },
                {
                  "durationMs": 604800000
                },
                {
                  "durationMs": 2592000000
                },
                {
                  "durationMs": 7776000000
                }
              ]
            }
          },
          {
            "id": "6a3b7f0e-1d52-4b8f-9a61-3c2f6e1d0a02",
            "version": "KqlParameterItem/1.0",
            "name": "Engine",
            "type": 2,
            "isRequired": true,
            "value": "All",
            "jsonData": "[\"All\",\"AzureAutomation\",\"LogicApps\",\"LocalAzureCli\"]",
            "typeSettings": {
              "showDefault": false
            }
          },
          {
            "id": "6a3b7f0e-1d52-4b8f-9a61-3c2f6e1d0a03",
            "version": "KqlParameterItem/1.0",
            "name": "Mode",
            "type": 2,
            "isRequired": true,
            "value": "All",
            "jsonData": "[\"All\",\"ReportOnly\",\"NotificationPilot\",\"DisablePilot\",\"Production\"]",
            "typeSettings": {
              "showDefault": false
            }
          }
        ]
      }
    },
    {
      "type": 3,
      "name": "panel1",
      "content": {
        "version": "KqlItem/1.0",
        "query": "let Latest = EntraStaleUser_CL\r\n| where TimeGenerated {TimeRange}\r\n| where RecordType == 'Evaluation'\r\n| where '{Engine}' == 'All' or Engine == '{Engine}'\r\n| where '{Mode}' == 'All' or Mode == '{Mode}'\r\n| summarize arg_max(TimeGenerated, *) by UserId;union\r\n  (Latest | summarize Value=count() | extend Metric='Evaluated users', Order=1),\r\n  (Latest | where Disposition in ('CandidateReportOnly','PendingSafetyBuffer','DisableCandidate') | summarize Value=count() | extend Metric='Inactive 30+ days', Order=2),\r\n  (Latest | where Disposition in ('NotifyUser','NotifyUserAndManager','ReviewTicket') | summarize Value=count() | extend Metric='Approaching (15-29 days)', Order=3),\r\n  (Latest | where Disposition == 'ManualReview' | summarize Value=count() | extend Metric='Manual review', Order=4),\r\n  (Latest | where Excluded == true | summarize Value=count() | extend Metric='Approved exclusions', Order=5),\r\n  (Latest | where ActionStatus in ('Failed','Blocked','PartialSuccess') or Disposition in ('Failed','BlockedRemediation') | summarize Value=count() | extend Metric='Failures or blocked', Order=6)\r\n| order by Order asc | project Metric, Value",
        "size": 4,
        "title": "Current status",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_ID__"
        ],
        "visualization": "tiles",
        "tileSettings": {
          "leftContent": {
            "formatter": 12,
            "columnMatch": "Value"
          },
          "showBorder": true,
          "titleContent": {
            "columnMatch": "Metric"
          }
        }
      }
    },
    {
      "type": 3,
      "name": "panel2",
      "content": {
        "version": "KqlItem/1.0",
        "query": "let Latest = EntraStaleUser_CL\r\n| where TimeGenerated {TimeRange}\r\n| where RecordType == 'Evaluation'\r\n| where '{Engine}' == 'All' or Engine == '{Engine}'\r\n| where '{Mode}' == 'All' or Mode == '{Mode}'\r\n| summarize arg_max(TimeGenerated, *) by UserId;Latest\r\n| where Disposition in ('CandidateReportOnly','PendingSafetyBuffer','DisableCandidate')\r\n| project UserPrincipalName, DisplayName, EmployeeType, LastSuccessfulSignInDateTime, DaysInactive, Disposition, Reason, PilotMember\r\n| order by DaysInactive desc",
        "size": 0,
        "title": "Inactive 30+ days (threshold reached)",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_ID__"
        ],
        "visualization": "table"
      }
    },
    {
      "type": 3,
      "name": "panel3",
      "content": {
        "version": "KqlItem/1.0",
        "query": "let Latest = EntraStaleUser_CL\r\n| where TimeGenerated {TimeRange}\r\n| where RecordType == 'Evaluation'\r\n| where '{Engine}' == 'All' or Engine == '{Engine}'\r\n| where '{Mode}' == 'All' or Mode == '{Mode}'\r\n| summarize arg_max(TimeGenerated, *) by UserId;Latest\r\n| extend Band = case(isnull(DaysInactive) or DaysInactive < 0, 'Unknown', DaysInactive < 15, '0-14', DaysInactive < 20, '15-19',\r\n                     DaysInactive < 25, '20-24', DaysInactive < 30, '25-29', '30+')\r\n| summarize Users=count() by Band\r\n| extend SortOrder=case(Band=='0-14',1,Band=='15-19',2,Band=='20-24',3,Band=='25-29',4,Band=='30+',5,6)\r\n| order by SortOrder asc | project Band, Users",
        "size": 0,
        "title": "Inactivity bands",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_ID__"
        ],
        "visualization": "barchart"
      }
    },
    {
      "type": 3,
      "name": "panel4",
      "content": {
        "version": "KqlItem/1.0",
        "query": "let Latest = EntraStaleUser_CL\r\n| where TimeGenerated {TimeRange}\r\n| where RecordType == 'Evaluation'\r\n| where '{Engine}' == 'All' or Engine == '{Engine}'\r\n| where '{Mode}' == 'All' or Mode == '{Mode}'\r\n| summarize arg_max(TimeGenerated, *) by UserId;Latest | summarize Users=count() by Disposition | order by Users desc",
        "size": 0,
        "title": "Disposition summary",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_ID__"
        ],
        "visualization": "piechart"
      }
    },
    {
      "type": 3,
      "name": "panel5",
      "content": {
        "version": "KqlItem/1.0",
        "query": "EntraStaleUser_CL\r\n| where TimeGenerated {TimeRange}\r\n| where '{Engine}' == 'All' or Engine == '{Engine}'\r\n| where '{Mode}' == 'All' or Mode == '{Mode}'| where RecordType == 'Evaluation'\r\n| summarize Inactive30Plus=dcountif(UserId, Disposition in ('CandidateReportOnly','PendingSafetyBuffer','DisableCandidate')),\r\n            Approaching=dcountif(UserId, Disposition in ('NotifyUser','NotifyUserAndManager','ReviewTicket')),\r\n            ManualReview=dcountif(UserId, ManualReview == true), Exclusions=dcountif(UserId, Excluded == true)\r\n  by bin(TimeGenerated, 1d)",
        "size": 0,
        "title": "Daily trend",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_ID__"
        ],
        "visualization": "timechart"
      }
    },
    {
      "type": 3,
      "name": "panel6",
      "content": {
        "version": "KqlItem/1.0",
        "query": "let Latest = EntraStaleUser_CL\r\n| where TimeGenerated {TimeRange}\r\n| where RecordType == 'Evaluation'\r\n| where '{Engine}' == 'All' or Engine == '{Engine}'\r\n| where '{Mode}' == 'All' or Mode == '{Mode}'\r\n| summarize arg_max(TimeGenerated, *) by UserId;Latest | where Excluded == true or ManualReview == true\r\n| project UserPrincipalName, DisplayName, EmployeeType, DaysInactive, Excluded, ManualReview, Reason, Details, TimeGenerated\r\n| order by ManualReview desc, DaysInactive desc",
        "size": 0,
        "title": "Exceptions and manual review",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_ID__"
        ],
        "visualization": "table"
      }
    },
    {
      "type": 3,
      "name": "panel7",
      "content": {
        "version": "KqlItem/1.0",
        "query": "EntraStaleUser_CL\r\n| where TimeGenerated {TimeRange}\r\n| where '{Engine}' == 'All' or Engine == '{Engine}'\r\n| where '{Mode}' == 'All' or Mode == '{Mode}'| summarize Evaluated=dcountif(UserId, RecordType == 'Evaluation'),\r\n            RunStarted=countif(RecordType == 'RunStarted'), RunCompleted=countif(RecordType == 'RunCompleted'),\r\n            RunFailed=countif(RecordType == 'RunFailed'), Blocked=countif(RecordType == 'Blocked'),\r\n            FirstRecord=min(TimeGenerated), LastRecord=max(TimeGenerated), Error=take_anyif(ErrorDetails, RecordType == 'RunFailed')\r\n  by RunId, Engine, Mode\r\n| extend Complete = RunStarted == 1 and RunCompleted == 1 and RunFailed == 0\r\n| order by LastRecord desc",
        "size": 0,
        "title": "Run health",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_ID__"
        ],
        "visualization": "table"
      }
    },
    {
      "type": 3,
      "name": "panel8",
      "content": {
        "version": "KqlItem/1.0",
        "query": "let Latest = EntraStaleUser_CL\r\n| where TimeGenerated {TimeRange}\r\n| where RecordType == 'Evaluation'\r\n| where '{Engine}' == 'All' or Engine == '{Engine}'\r\n| where '{Mode}' == 'All' or Mode == '{Mode}'\r\n| summarize arg_max(TimeGenerated, *) by UserId;union\r\n  (Latest | where isempty(UserId) | summarize Value=count() | extend Check='Missing UserId'),\r\n  (Latest | where isempty(UserPrincipalName) | summarize Value=count() | extend Check='Missing UPN'),\r\n  (Latest | where isnull(LastSuccessfulSignInDateTime) and Disposition != 'Skipped' | summarize Value=count() | extend Check='Null successful sign-in (in scope)'),\r\n  (Latest | where DaysInactive < -1 | summarize Value=count() | extend Check='Invalid DaysInactive'),\r\n  (Latest | where Excluded == true and Disposition in ('DisableCandidate','CandidateReportOnly') | summarize Value=count() | extend Check='SAFETY: Excluded but candidate'),\r\n  (Latest | where ManualReview == true and Disposition in ('DisableCandidate','CandidateReportOnly') | summarize Value=count() | extend Check='SAFETY: Manual review but candidate')\r\n| project Check, Value",
        "size": 0,
        "title": "Data quality (non-zero safety rows must be investigated)",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_ID__"
        ],
        "visualization": "table"
      }
    }
  ],
  "fallbackResourceIds": [
    "__WORKSPACE_ID__"
  ]
}
